}

.wf-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.spacer {
  flex: 1;
}

.btn.danger {
  color: var(--red);
}

.btn.danger:hover:not(:disabled) {
  border-color: var(--red);
  color: var(--red);
}

@media (max-width: 700px) {
  .wf-route {
    flex-direction: column;
    gap: 4px;
  }

  .wf-route-label {
    padding-top: 0;
  }
}
